const MOCK3_SECTIONS = [{"id": "english", "title": "English Language", "questions": [{"topic": "RC", "question": "<div style=\"background:#F4F6FA;border:1px solid #E1E5EE;border-radius:8px;padding:14px 16px;margin-bottom:14px;font-weight:400;font-size:0.92rem;line-height:1.6;color:#333;\"><b>Reading Comprehension — Read the passage, then answer Q1&ndash;Q5:</b><br/><br/>Smart city initiatives promise to optimize everything from traffic flow to energy consumption through networks of sensors and real-time data analytics, yet the enthusiasm surrounding these projects often outpaces careful consideration of who actually benefits. Municipal governments, eager to attract investment and burnish their reputations as forward-thinking, frequently partner with technology vendors whose proprietary systems lock cities into long-term contracts with limited transparency about how collected data is used or monetized. Residents in lower-income neighborhoods, meanwhile, often see fewer sensors and less responsive services than their more affluent counterparts, reproducing existing inequities under a veneer of technological neutrality. Proponents counter that even imperfect implementations generate valuable efficiency gains, and that transparency requirements can be strengthened over time through updated procurement policies. Critics respond that by the time such safeguards are enacted, vendors have often already entrenched themselves so deeply into municipal infrastructure that meaningful renegotiation becomes practically impossible. The debate ultimately turns on a familiar tension: the appeal of near-term technical solutions versus the slower, harder work of building accountable governance structures capable of adapting as technology evolves.</div><b>Q:</b> According to the passage, what is a common outcome for residents in lower-income neighborhoods under smart city initiatives?", "options": ["They receive priority access to new sensors", "They often see fewer sensors and less responsive services than affluent areas, reproducing existing inequities", "They are excluded entirely from city services", "They receive the same services as more affluent areas", "They control the technology vendors' contracts"], "correct": "B", "explanation": "The passage states residents in lower-income neighborhoods 'often see fewer sensors and less responsive services than their more affluent counterparts, reproducing existing inequities under a veneer of technological neutrality.'"}, {"topic": "RC", "question": "<div style=\"background:#F4F6FA;border:1px solid #E1E5EE;border-radius:8px;padding:14px 16px;margin-bottom:14px;font-weight:400;font-size:0.92rem;line-height:1.6;color:#333;\"><b>Reading Comprehension — Read the passage, then answer Q1&ndash;Q5:</b><br/><br/>Smart city initiatives promise to optimize everything from traffic flow to energy consumption through networks of sensors and real-time data analytics, yet the enthusiasm surrounding these projects often outpaces careful consideration of who actually benefits. Municipal governments, eager to attract investment and burnish their reputations as forward-thinking, frequently partner with technology vendors whose proprietary systems lock cities into long-term contracts with limited transparency about how collected data is used or monetized. Residents in lower-income neighborhoods, meanwhile, often see fewer sensors and less responsive services than their more affluent counterparts, reproducing existing inequities under a veneer of technological neutrality. Proponents counter that even imperfect implementations generate valuable efficiency gains, and that transparency requirements can be strengthened over time through updated procurement policies. Critics respond that by the time such safeguards are enacted, vendors have often already entrenched themselves so deeply into municipal infrastructure that meaningful renegotiation becomes practically impossible. The debate ultimately turns on a familiar tension: the appeal of near-term technical solutions versus the slower, harder work of building accountable governance structures capable of adapting as technology evolves.</div><b>Q:</b> What concern does the passage raise about municipal partnerships with technology vendors?", "options": ["Vendors always operate at a financial loss", "Proprietary systems can lock cities into long-term contracts with limited transparency about data use", "Vendors are legally barred from monetizing data", "Municipal governments never sign contracts with vendors", "Technology vendors have no interest in smart city projects"], "correct": "B", "explanation": "The passage states vendors' 'proprietary systems lock cities into long-term contracts with limited transparency about how collected data is used or monetized.'"}, {"topic": "RC", "question": "<div style=\"background:#F4F6FA;border:1px solid #E1E5EE;border-radius:8px;padding:14px 16px;margin-bottom:14px;font-weight:400;font-size:0.92rem;line-height:1.6;color:#333;\"><b>Reading Comprehension — Read the passage, then answer Q1&ndash;Q5:</b><br/><br/>Smart city initiatives promise to optimize everything from traffic flow to energy consumption through networks of sensors and real-time data analytics, yet the enthusiasm surrounding these projects often outpaces careful consideration of who actually benefits. Municipal governments, eager to attract investment and burnish their reputations as forward-thinking, frequently partner with technology vendors whose proprietary systems lock cities into long-term contracts with limited transparency about how collected data is used or monetized. Residents in lower-income neighborhoods, meanwhile, often see fewer sensors and less responsive services than their more affluent counterparts, reproducing existing inequities under a veneer of technological neutrality. Proponents counter that even imperfect implementations generate valuable efficiency gains, and that transparency requirements can be strengthened over time through updated procurement policies. Critics respond that by the time such safeguards are enacted, vendors have often already entrenched themselves so deeply into municipal infrastructure that meaningful renegotiation becomes practically impossible. The debate ultimately turns on a familiar tension: the appeal of near-term technical solutions versus the slower, harder work of building accountable governance structures capable of adapting as technology evolves.</div><b>Q:</b> What is the proponents' counter-argument mentioned in the passage?", "options": ["Smart cities should be abandoned entirely", "Even imperfect implementations generate valuable efficiency gains, and transparency can improve over time", "Data privacy is not a real concern", "Only wealthy neighborhoods should receive smart city technology", "Vendors should be banned from all municipal contracts"], "correct": "B", "explanation": "The passage states 'Proponents counter that even imperfect implementations generate valuable efficiency gains, and that transparency requirements can be strengthened over time.'"}, {"topic": "RC", "question": "<div style=\"background:#F4F6FA;border:1px solid #E1E5EE;border-radius:8px;padding:14px 16px;margin-bottom:14px;font-weight:400;font-size:0.92rem;line-height:1.6;color:#333;\"><b>Reading Comprehension — Read the passage, then answer Q1&ndash;Q5:</b><br/><br/>Smart city initiatives promise to optimize everything from traffic flow to energy consumption through networks of sensors and real-time data analytics, yet the enthusiasm surrounding these projects often outpaces careful consideration of who actually benefits. Municipal governments, eager to attract investment and burnish their reputations as forward-thinking, frequently partner with technology vendors whose proprietary systems lock cities into long-term contracts with limited transparency about how collected data is used or monetized. Residents in lower-income neighborhoods, meanwhile, often see fewer sensors and less responsive services than their more affluent counterparts, reproducing existing inequities under a veneer of technological neutrality. Proponents counter that even imperfect implementations generate valuable efficiency gains, and that transparency requirements can be strengthened over time through updated procurement policies. Critics respond that by the time such safeguards are enacted, vendors have often already entrenched themselves so deeply into municipal infrastructure that meaningful renegotiation becomes practically impossible. The debate ultimately turns on a familiar tension: the appeal of near-term technical solutions versus the slower, harder work of building accountable governance structures capable of adapting as technology evolves.</div><b>Q:</b> According to critics, why do safeguards often come too late?", "options": ["Because vendors are never willing to negotiate", "Because by the time safeguards are enacted, vendors are often already too entrenched in infrastructure for meaningful renegotiation", "Because cities lack the legal authority to enact any safeguards", "Because residents oppose all forms of regulation", "Because technology becomes obsolete before safeguards can be written"], "correct": "B", "explanation": "The passage states critics respond that 'by the time such safeguards are enacted, vendors have often already entrenched themselves so deeply into municipal infrastructure that meaningful renegotiation becomes practically impossible.'"}, {"topic": "RC", "question": "<div style=\"background:#F4F6FA;border:1px solid #E1E5EE;border-radius:8px;padding:14px 16px;margin-bottom:14px;font-weight:400;font-size:0.92rem;line-height:1.6;color:#333;\"><b>Reading Comprehension — Read the passage, then answer Q1&ndash;Q5:</b><br/><br/>Smart city initiatives promise to optimize everything from traffic flow to energy consumption through networks of sensors and real-time data analytics, yet the enthusiasm surrounding these projects often outpaces careful consideration of who actually benefits. Municipal governments, eager to attract investment and burnish their reputations as forward-thinking, frequently partner with technology vendors whose proprietary systems lock cities into long-term contracts with limited transparency about how collected data is used or monetized. Residents in lower-income neighborhoods, meanwhile, often see fewer sensors and less responsive services than their more affluent counterparts, reproducing existing inequities under a veneer of technological neutrality. Proponents counter that even imperfect implementations generate valuable efficiency gains, and that transparency requirements can be strengthened over time through updated procurement policies. Critics respond that by the time such safeguards are enacted, vendors have often already entrenched themselves so deeply into municipal infrastructure that meaningful renegotiation becomes practically impossible. The debate ultimately turns on a familiar tension: the appeal of near-term technical solutions versus the slower, harder work of building accountable governance structures capable of adapting as technology evolves.</div><b>Q:</b> What tension does the passage identify as central to the smart city debate?", "options": ["The appeal of near-term technical solutions versus the slower work of building accountable governance structures", "The choice between public and private funding sources only", "A conflict between two competing technology vendors", "The debate between urban and rural development priorities", "A purely aesthetic disagreement about sensor design"], "correct": "A", "explanation": "The passage's final sentence states the debate 'turns on a familiar tension: the appeal of near-term technical solutions versus the slower, harder work of building accountable governance structures.'"}, {"topic": "Cloze", "question": "<div style=\"background:#F4F6FA;border:1px solid #E1E5EE;border-radius:8px;padding:14px 16px;margin-bottom:14px;font-weight:400;font-size:0.92rem;line-height:1.6;color:#333;\"><b>Cloze Test — Read the passage, then choose the best word for each blank (Q6&ndash;Q10):</b><br/><br/>Commercial space enterprises have (1)_____ the traditional model in which only national governments could afford to launch payloads into orbit. By radically (2)_____ launch costs through reusable rocket technology, private firms have made space more accessible to universities, startups, and even hobbyist groups. This democratization, however, has also (3)_____ concerns about orbital congestion, as thousands of small satellites now compete for limited operational altitudes. Regulators have been slow to (4)_____ comprehensive frameworks for managing this traffic, leaving much of the coordination to voluntary agreements between operators. Some experts warn that without binding international rules, a single catastrophic collision could (5)_____ a cascade of debris that renders certain orbits unusable for generations.</div><b>Q:</b> Blank (1):", "options": ["reinforced", "upended", "ignored", "funded", "delayed"], "correct": "B", "explanation": "'Upended' fits — commercial space enterprises overturned the old model where only governments could launch payloads."}, {"topic": "Cloze", "question": "<div style=\"background:#F4F6FA;border:1px solid #E1E5EE;border-radius:8px;padding:14px 16px;margin-bottom:14px;font-weight:400;font-size:0.92rem;line-height:1.6;color:#333;\"><b>Cloze Test — Read the passage, then choose the best word for each blank (Q6&ndash;Q10):</b><br/><br/>Commercial space enterprises have (1)_____ the traditional model in which only national governments could afford to launch payloads into orbit. By radically (2)_____ launch costs through reusable rocket technology, private firms have made space more accessible to universities, startups, and even hobbyist groups. This democratization, however, has also (3)_____ concerns about orbital congestion, as thousands of small satellites now compete for limited operational altitudes. Regulators have been slow to (4)_____ comprehensive frameworks for managing this traffic, leaving much of the coordination to voluntary agreements between operators. Some experts warn that without binding international rules, a single catastrophic collision could (5)_____ a cascade of debris that renders certain orbits unusable for generations.</div><b>Q:</b> Blank (2):", "options": ["increasing", "raising", "reducing", "ignoring", "stabilizing"], "correct": "C", "explanation": "'Reducing' fits — reusable rocket technology lowers launch costs, which is what made space more accessible."}, {"topic": "Cloze", "question": "<div style=\"background:#F4F6FA;border:1px solid #E1E5EE;border-radius:8px;padding:14px 16px;margin-bottom:14px;font-weight:400;font-size:0.92rem;line-height:1.6;color:#333;\"><b>Cloze Test — Read the passage, then choose the best word for each blank (Q6&ndash;Q10):</b><br/><br/>Commercial space enterprises have (1)_____ the traditional model in which only national governments could afford to launch payloads into orbit. By radically (2)_____ launch costs through reusable rocket technology, private firms have made space more accessible to universities, startups, and even hobbyist groups. This democratization, however, has also (3)_____ concerns about orbital congestion, as thousands of small satellites now compete for limited operational altitudes. Regulators have been slow to (4)_____ comprehensive frameworks for managing this traffic, leaving much of the coordination to voluntary agreements between operators. Some experts warn that without binding international rules, a single catastrophic collision could (5)_____ a cascade of debris that renders certain orbits unusable for generations.</div><b>Q:</b> Blank (3):", "options": ["eliminated", "raised", "resolved", "prevented", "calmed"], "correct": "B", "explanation": "'Raised' fits — the democratization of space access has also raised (created) new concerns about orbital congestion."}, {"topic": "Cloze", "question": "<div style=\"background:#F4F6FA;border:1px solid #E1E5EE;border-radius:8px;padding:14px 16px;margin-bottom:14px;font-weight:400;font-size:0.92rem;line-height:1.6;color:#333;\"><b>Cloze Test — Read the passage, then choose the best word for each blank (Q6&ndash;Q10):</b><br/><br/>Commercial space enterprises have (1)_____ the traditional model in which only national governments could afford to launch payloads into orbit. By radically (2)_____ launch costs through reusable rocket technology, private firms have made space more accessible to universities, startups, and even hobbyist groups. This democratization, however, has also (3)_____ concerns about orbital congestion, as thousands of small satellites now compete for limited operational altitudes. Regulators have been slow to (4)_____ comprehensive frameworks for managing this traffic, leaving much of the coordination to voluntary agreements between operators. Some experts warn that without binding international rules, a single catastrophic collision could (5)_____ a cascade of debris that renders certain orbits unusable for generations.</div><b>Q:</b> Blank (4):", "options": ["abandon", "establish", "forget", "sell", "weaken"], "correct": "B", "explanation": "'Establish' fits — regulators have been slow to create comprehensive frameworks for managing satellite traffic."}, {"topic": "Cloze", "question": "<div style=\"background:#F4F6FA;border:1px solid #E1E5EE;border-radius:8px;padding:14px 16px;margin-bottom:14px;font-weight:400;font-size:0.92rem;line-height:1.6;color:#333;\"><b>Cloze Test — Read the passage, then choose the best word for each blank (Q6&ndash;Q10):</b><br/><br/>Commercial space enterprises have (1)_____ the traditional model in which only national governments could afford to launch payloads into orbit. By radically (2)_____ launch costs through reusable rocket technology, private firms have made space more accessible to universities, startups, and even hobbyist groups. This democratization, however, has also (3)_____ concerns about orbital congestion, as thousands of small satellites now compete for limited operational altitudes. Regulators have been slow to (4)_____ comprehensive frameworks for managing this traffic, leaving much of the coordination to voluntary agreements between operators. Some experts warn that without binding international rules, a single catastrophic collision could (5)_____ a cascade of debris that renders certain orbits unusable for generations.</div><b>Q:</b> Blank (5):", "options": ["prevent", "trigger", "calm", "resolve", "ignore"], "correct": "B", "explanation": "'Trigger' fits — a catastrophic collision could set off (trigger) a cascade of debris, consistent with the warning tone."}, {"topic": "Error Spotting", "question": "Neither the CEO nor the board members was aware (A) / of the extent of the financial discrepancies (B) / until the external auditors (C) / submitted their final report (D) / No error (E)", "options": ["A", "B", "C", "D", "E"], "correct": "A", "explanation": "With 'neither...nor', the verb agrees with the subject CLOSER to it — here 'board members' (plural) is closer, so it should be 'were aware', not 'was aware'. The error is in part (A)."}, {"topic": "Error Spotting", "question": "The team of researchers have published (A) / their findings in a peer-reviewed journal (B) / after nearly a decade (C) / of painstaking laboratory work (D) / No error (E)", "options": ["A", "B", "C", "D", "E"], "correct": "A", "explanation": "'The team' is the subject (a singular collective noun here), so the verb should be 'has published', not 'have published'. The error is in part (A)."}, {"topic": "Error Spotting", "question": "By the time the ambulance arrived, (A) / the patient had already regained (B) / consciousness and was sitting up (C) / on his own accord (D) / No error (E)", "options": ["A", "B", "C", "D", "E"], "correct": "D", "explanation": "The correct idiom is 'of his own accord' (meaning voluntarily), not 'on his own accord'. The error is in part (D)."}, {"topic": "Error Spotting", "question": "Having finished the marathon in record time, (A) / the trophy was awarded to her (B) / by the event organizers (C) / amid thunderous applause (D) / No error (E)", "options": ["A", "B", "C", "D", "E"], "correct": "B", "explanation": "This is a dangling modifier: 'Having finished the marathon' must logically modify a person, but part (B) makes 'the trophy' the grammatical subject (the trophy didn't finish the marathon). It should read '...she was awarded the trophy...'. The error is in part (B)."}, {"topic": "Error Spotting", "question": "The manager along with his entire team were present (A) / at the inauguration ceremony (B) / to receive the visiting dignitaries (C) / from the parent company (D) / No error (E)", "options": ["A", "B", "C", "D", "E"], "correct": "A", "explanation": "'Along with his entire team' is a parenthetical phrase and does not make the subject plural. The subject is 'The manager' (singular), so the verb should be 'was present', not 'were present'. The error is in part (A)."}, {"topic": "Sentence Improvement", "question": "The board recommended that the new policy <u>is implemented</u> immediately.", "options": ["is implemented", "be implemented", "will be implemented", "was implemented", "No improvement needed"], "correct": "B", "explanation": "After verbs expressing recommendation/demand ('recommended that'), formal grammar requires the subjunctive mood — the base form 'be implemented', not 'is implemented'."}, {"topic": "Sentence Improvement", "question": "No sooner had the announcement been made <u>than</u> the stock price began to fall.", "options": ["than", "when", "then", "that", "No improvement needed"], "correct": "E", "explanation": "This is correct: 'No sooner...than' is the standard correlative pairing used for this construction (contrast with 'Scarcely/Hardly...when')."}, {"topic": "Sentence Improvement", "question": "She is one of the few executives <u>who has</u> successfully navigated three separate corporate mergers.", "options": ["who has", "who have", "which has", "that is having", "No improvement needed"], "correct": "B", "explanation": "In the construction 'one of the few X who...', the relative clause verb agrees with the plural antecedent 'executives', so it should be 'who have', not 'who has'."}, {"topic": "Sentence Improvement", "question": "The committee's decision, along with the accompanying recommendations, <u>are expected</u> to be released next week.", "options": ["are expected", "is expected", "were expected", "have been expected", "No improvement needed"], "correct": "B", "explanation": "'Along with the accompanying recommendations' is a parenthetical phrase and does not pluralize the subject. The subject is 'The committee's decision' (singular), so it should be 'is expected'."}, {"topic": "Double Blanks", "question": "The startup's founders were praised for their _____ approach to hiring, even as insiders quietly admitted that the rapid growth had left onboarding processes _____ .", "options": ["innovative, refined", "meticulous, disorganized", "careless, streamlined", "rigid, flexible", "transparent, secretive"], "correct": "B", "explanation": "The sentence contrasts external praise with an internal admission ('even as insiders quietly admitted'). The praised quality is positive ('meticulous'), while the admitted problem is negative ('disorganized')."}, {"topic": "Double Blanks", "question": "Although the negotiations appeared _____ to outside observers, insiders described the atmosphere in the room as _____ .", "options": ["cordial, tense", "hostile, calm", "productive, chaotic", "calm, relaxed", "tense, cordial"], "correct": "A", "explanation": "'Although X to outsiders, insiders described Y' sets up a contrast between outward appearance and inside reality — 'cordial' (calm appearance) versus 'tense' (the real atmosphere)."}, {"topic": "Para Jumble", "question": "<div style=\"background:#F4F6FA;border:1px solid #E1E5EE;border-radius:8px;padding:14px 16px;margin-bottom:14px;font-weight:400;font-size:0.92rem;line-height:1.6;color:#333;\"><b>Para Jumble — Read sentences P, Q, R, S, then answer:</b><br/><br/>P: This pattern reversed sharply after the pandemic, as remote work loosened the link between employment and physical location.<br/>Q: For most of the twentieth century, migration flowed steadily from rural regions toward major metropolitan centers in search of employment.<br/>R: Many workers relocated to smaller towns offering lower costs of living without sacrificing their urban salaries.<br/>S: Local economies in these smaller towns have since had to adapt rapidly to accommodate a wave of new residents with different expectations.</div><b>Q:</b> Choose the correct sequence:", "options": ["QPRS", "QRPS", "PQRS", "QPSR", "RQPS"], "correct": "A", "explanation": "Logical flow: Q (the historical pattern of rural-to-urban migration) then P (this pattern reversed after the pandemic) then R (workers relocated to smaller towns) then S (local economies adapting to the influx). The correct order is QPRS."}, {"topic": "Para Jumble", "question": "<div style=\"background:#F4F6FA;border:1px solid #E1E5EE;border-radius:8px;padding:14px 16px;margin-bottom:14px;font-weight:400;font-size:0.92rem;line-height:1.6;color:#333;\"><b>Para Jumble — Read sentences P, Q, R, S, then answer:</b><br/><br/>P: Critics argue that abrupt subsidy withdrawal risks destabilizing an industry still dependent on policy support.<br/>Q: Governments across several countries introduced generous subsidies for solar panel manufacturers in the early 2010s.<br/>R: These incentives helped domestic industries scale production and drove down costs significantly over the following decade.<br/>S: As costs fell, some policymakers began questioning whether continued subsidies were still necessary.</div><b>Q:</b> Choose the correct sequence:", "options": ["QRSP", "QSRP", "RQSP", "QRPS", "SQRP"], "correct": "A", "explanation": "Logical flow: Q (subsidies introduced) then R (incentives helped scale production, driving down costs) then S (as costs fell, policymakers questioned the subsidies) then P (critics respond to that questioning, warning against abrupt withdrawal). The correct order is QRSP."}, {"topic": "Vocabulary", "question": "Choose the word most SIMILAR in meaning to 'EPHEMERAL'.", "options": ["Permanent", "Lasting only a very short time", "Extremely durable", "Ancient", "Widespread"], "correct": "B", "explanation": "'Ephemeral' describes something that lasts for a very short time, i.e., fleeting or transient."}, {"topic": "Vocabulary", "question": "Choose the word most OPPOSITE in meaning to 'AUSTERE'.", "options": ["Plain", "Lavish or luxurious", "Strict", "Simple", "Harsh"], "correct": "B", "explanation": "'Austere' means severely simple, plain, or self-disciplined (without luxury). Its opposite is 'Lavish' or 'Luxurious'."}]}, {"id": "quant", "title": "Quantitative Aptitude", "questions": [{"topic": "Simplification", "question": "(24% of 450) + (16% of 375) = ?", "options": ["158", "163", "168", "173", "178"], "correct": "C", "explanation": "24% of 450 = 108. 16% of 375 = 60. Sum = 108 + 60 = 168."}, {"topic": "Simplification", "question": "(5/9 of 729) - (2/7 of 350) = ?", "options": ["295", "300", "305", "310", "315"], "correct": "C", "explanation": "5/9 of 729 = 405. 2/7 of 350 = 100. Difference = 405 - 100 = 305."}, {"topic": "Number Series", "question": "Find the next number in the series: 7, 15, 31, 63, 127, ?", "options": ["245", "250", "255", "260", "265"], "correct": "C", "explanation": "Each term follows the pattern: (previous term × 2) + 1. 7×2+1=15, 15×2+1=31, 31×2+1=63, 63×2+1=127, 127×2+1=255."}, {"topic": "Number Series", "question": "Find the WRONG number in the series: 5, 6, 14, 45, 184, 924", "options": ["6", "14", "45", "184", "924"], "correct": "E", "explanation": "Each term follows: (previous term × step) + step, where step increases 1,2,3,4,5. 5×1+1=6, 6×2+2=14, 14×3+3=45, 45×4+4=184, 184×5+5=925 (not 924). So 924 is wrong; it should be 925."}, {"topic": "Quadratic Equations", "question": "I. x<sup>2</sup> - 11x + 30 = 0    II. y<sup>2</sup> - 13y + 42 = 0", "options": ["x &gt; y", "x &lt; y", "x ≤ y", "x ≥ y", "No relation can be established"], "correct": "C", "explanation": "Equation I: x²-11x+30=0 → (x-5)(x-6)=0 → x = 5 or 6. Equation II: y²-13y+42=0 → (y-6)(y-7)=0 → y = 6 or 7. Checking combinations: (x=5,y=6)→x<y; (x=5,y=7)→x<y; (x=6,y=6)→x=y; (x=6,y=7)→x<y. Since x is always less than or equal to y, the relationship is x ≤ y."}, {"topic": "Quadratic Equations", "question": "I. 2x<sup>2</sup> - 7x + 3 = 0    II. 3y<sup>2</sup> - 8y + 4 = 0", "options": ["x &gt; y", "x &lt; y", "x ≤ y", "x ≥ y", "No relation can be established"], "correct": "E", "explanation": "Equation I: 2x²-7x+3=0 → x = 3 or 0.5. Equation II: 3y²-8y+4=0 → y = 2 or 0.667. Checking combinations: (x=3,y=2)→x>y; (x=3,y=0.667)→x>y; (x=0.5,y=2)→x<y; (x=0.5,y=0.667)→x<y. Since results are mixed, no definite relationship can be established."}, {"topic": "Percentage", "question": "The price of an item is first decreased by 30% and then increased by 40%. What is the net percentage change in the price?", "options": ["-2%", "+2%", "-5%", "+5%", "0% (no change)"], "correct": "A", "explanation": "Net multiplying factor = 0.70 × 1.40 = 0.98, i.e., 98% of the original price — a net decrease of 2%."}, {"topic": "Percentage", "question": "In an exam, 65% of the candidates passed. If 210 candidates failed, how many candidates appeared for the exam in total?", "options": ["550", "580", "600", "620", "650"], "correct": "C", "explanation": "Failed% = 100% - 65% = 35%, which corresponds to 210 candidates. So 1% = 6 candidates, and total = 6 × 100 = 600."}, {"topic": "Profit & Loss", "question": "A retailer buys an article for Rs. 1,200 and sells it at a loss of 8%. Find the selling price.", "options": ["Rs. 1,084", "Rs. 1,094", "Rs. 1,104", "Rs. 1,114", "Rs. 1,124"], "correct": "C", "explanation": "Selling Price = Cost Price × (1 - Loss%/100) = 1,200 × 0.92 = Rs. 1,104."}, {"topic": "Profit & Loss", "question": "A man sold two articles, each for Rs. 1,980. On one he gained 10% and on the other he lost 10%. Find his overall gain or loss percentage.", "options": ["1% gain", "1% loss", "No profit no loss", "2% loss", "2% gain"], "correct": "B", "explanation": "When two items are sold at the SAME selling price with equal %gain and %loss, there is always an overall LOSS, equal to (common%)²/100 = (10)²/100 = 1%. So the overall result is a 1% loss."}, {"topic": "Simple Interest", "question": "Find the simple interest on Rs. 12,500 at 9% per annum for 4 years.", "options": ["Rs. 4,200", "Rs. 4,300", "Rs. 4,400", "Rs. 4,500", "Rs. 4,600"], "correct": "D", "explanation": "Simple Interest = (Principal × Rate × Time)/100 = (12,500 × 9 × 4)/100 = Rs. 4,500."}, {"topic": "Compound Interest", "question": "A sum of Rs. 5,000 becomes Rs. 6,050 in 2 years at compound interest, compounded annually. Find the rate of interest.", "options": ["8%", "9%", "10%", "11%", "12%"], "correct": "C", "explanation": "6,050/5,000 = 1.21 = (1+r/100)². Taking square root: 1+r/100 = 1.1, so r = 10%."}, {"topic": "Ratio & Proportion", "question": "Two numbers are in the ratio 5:7. If 8 is subtracted from each, the ratio becomes 3:5. Find the smaller of the two original numbers.", "options": ["18", "20", "22", "24", "26"], "correct": "B", "explanation": "Let the numbers be 5x and 7x. (5x-8)/(7x-8) = 3/5 → 5(5x-8) = 3(7x-8) → 25x-40 = 21x-24 → 4x = 16 → x = 4. The smaller number = 5x = 20."}, {"topic": "Ratio & Proportion", "question": "If A:B = 3:4 and B:C = 6:7, find A:B:C.", "options": ["9:12:14", "3:4:7", "6:8:14", "9:14:12", "3:12:14"], "correct": "A", "explanation": "Make B's value common: A:B = 3:4 = 9:12 (×3), and B:C = 6:7 = 12:14 (×2). Now B matches at 12 in both. So A:B:C = 9:12:14."}, {"topic": "Average", "question": "The average of 7 consecutive odd numbers is 51. Find the largest of these numbers.", "options": ["53", "55", "57", "59", "61"], "correct": "C", "explanation": "For 7 consecutive odd numbers, the average equals the middle (4th) term, so the 4th term = 51. The numbers are 45, 47, 49, 51, 53, 55, 57. The largest is 57."}, {"topic": "Average", "question": "The average salary of 20 employees is Rs. 32,000. If the manager's salary of Rs. 74,000 is also included, find the new average salary.", "options": ["Rs. 33,000", "Rs. 33,500", "Rs. 34,000", "Rs. 34,500", "Rs. 35,000"], "correct": "C", "explanation": "Total salary of 20 employees = 20 × 32,000 = Rs. 6,40,000. Including the manager: new total = 6,40,000 + 74,000 = Rs. 7,14,000, over 21 people. New average = 7,14,000/21 = Rs. 34,000."}, {"topic": "Time & Work", "question": "A can complete a work in 15 days, B in 10 days. They work together for 3 days, then A leaves. In how many more days will B alone finish the remaining work?", "options": ["4 days", "5 days", "6 days", "7 days", "8 days"], "correct": "B", "explanation": "A's rate = 1/15, B's rate = 1/10. Combined rate = 1/15+1/10 = 2/30+3/30 = 5/30 = 1/6. Work done in 3 days = 3/6 = 1/2, leaving 1/2 of the work. B alone needs (1/2) ÷ (1/10) = 5 days to finish it."}, {"topic": "Time & Work", "question": "12 men can complete a work in 18 days. In how many days can 8 men complete the same work?", "options": ["24 days", "25 days", "26 days", "27 days", "28 days"], "correct": "D", "explanation": "Total work = 12 × 18 = 216 man-days. With 8 men, days required = 216/8 = 27 days."}, {"topic": "Boats & Streams", "question": "A man rows 30 km downstream in 3 hours and returns upstream in 5 hours. Find the speed of the stream.", "options": ["1 km/h", "1.5 km/h", "2 km/h", "2.5 km/h", "3 km/h"], "correct": "C", "explanation": "Downstream speed = 30/3 = 10 km/h. Upstream speed = 30/5 = 6 km/h. Speed of stream = (10-6)/2 = 2 km/h."}, {"topic": "Time-Speed-Distance", "question": "A train 200 m long crosses a platform 300 m long in 25 seconds. Find the speed of the train in km/h.", "options": ["64 km/h", "68 km/h", "72 km/h", "76 km/h", "80 km/h"], "correct": "C", "explanation": "Total distance to cross = 200 + 300 = 500 m. Speed = 500/25 = 20 m/s. Converting to km/h: 20 × 18/5 = 72 km/h."}, {"topic": "Data Interpretation", "question": "<div style=\"background:#F4F6FA;border:1px solid #E1E5EE;border-radius:8px;padding:14px 16px;margin-bottom:14px;font-weight:400;font-size:0.92rem;line-height:1.6;color:#333;\"><b>Data Interpretation — Study the table, then answer Q21&ndash;Q23:</b><br/><br/>Number of students enrolled in 4 courses over 3 years:<br/><table style=\"width:100%;border-collapse:collapse;margin-top:8px;font-size:0.9rem;\"><tr style=\"background:#0D1B4C;color:white;\"><th style=\"padding:6px 10px;border:1px solid #ccc;text-align:left;\">Course</th><th style=\"padding:6px 10px;border:1px solid #ccc;\">2022</th><th style=\"padding:6px 10px;border:1px solid #ccc;\">2023</th><th style=\"padding:6px 10px;border:1px solid #ccc;\">2024</th></tr><tr><td style=\"padding:6px 10px;border:1px solid #ccc;\">C1</td><td style=\"padding:6px 10px;border:1px solid #ccc;text-align:center;\">80</td><td style=\"padding:6px 10px;border:1px solid #ccc;text-align:center;\">95</td><td style=\"padding:6px 10px;border:1px solid #ccc;text-align:center;\">110</td></tr><tr style=\"background:#EEF2FA;\"><td style=\"padding:6px 10px;border:1px solid #ccc;\">C2</td><td style=\"padding:6px 10px;border:1px solid #ccc;text-align:center;\">60</td><td style=\"padding:6px 10px;border:1px solid #ccc;text-align:center;\">65</td><td style=\"padding:6px 10px;border:1px solid #ccc;text-align:center;\">75</td></tr><tr><td style=\"padding:6px 10px;border:1px solid #ccc;\">C3</td><td style=\"padding:6px 10px;border:1px solid #ccc;text-align:center;\">100</td><td style=\"padding:6px 10px;border:1px solid #ccc;text-align:center;\">90</td><td style=\"padding:6px 10px;border:1px solid #ccc;text-align:center;\">105</td></tr><tr style=\"background:#EEF2FA;\"><td style=\"padding:6px 10px;border:1px solid #ccc;\">C4</td><td style=\"padding:6px 10px;border:1px solid #ccc;text-align:center;\">40</td><td style=\"padding:6px 10px;border:1px solid #ccc;text-align:center;\">55</td><td style=\"padding:6px 10px;border:1px solid #ccc;text-align:center;\">60</td></tr></table></div><b>Q:</b> What is the total enrollment across all 4 courses in 2024?", "options": ["330", "340", "350", "360", "370"], "correct": "C", "explanation": "Total 2024 enrollment = 110 (C1) + 75 (C2) + 105 (C3) + 60 (C4) = 350."}, {"topic": "Data Interpretation", "question": "<div style=\"background:#F4F6FA;border:1px solid #E1E5EE;border-radius:8px;padding:14px 16px;margin-bottom:14px;font-weight:400;font-size:0.92rem;line-height:1.6;color:#333;\"><b>Data Interpretation — Study the table, then answer Q21&ndash;Q23:</b><br/><br/>Number of students enrolled in 4 courses over 3 years:<br/><table style=\"width:100%;border-collapse:collapse;margin-top:8px;font-size:0.9rem;\"><tr style=\"background:#0D1B4C;color:white;\"><th style=\"padding:6px 10px;border:1px solid #ccc;text-align:left;\">Course</th><th style=\"padding:6px 10px;border:1px solid #ccc;\">2022</th><th style=\"padding:6px 10px;border:1px solid #ccc;\">2023</th><th style=\"padding:6px 10px;border:1px solid #ccc;\">2024</th></tr><tr><td style=\"padding:6px 10px;border:1px solid #ccc;\">C1</td><td style=\"padding:6px 10px;border:1px solid #ccc;text-align:center;\">80</td><td style=\"padding:6px 10px;border:1px solid #ccc;text-align:center;\">95</td><td style=\"padding:6px 10px;border:1px solid #ccc;text-align:center;\">110</td></tr><tr style=\"background:#EEF2FA;\"><td style=\"padding:6px 10px;border:1px solid #ccc;\">C2</td><td style=\"padding:6px 10px;border:1px solid #ccc;text-align:center;\">60</td><td style=\"padding:6px 10px;border:1px solid #ccc;text-align:center;\">65</td><td style=\"padding:6px 10px;border:1px solid #ccc;text-align:center;\">75</td></tr><tr><td style=\"padding:6px 10px;border:1px solid #ccc;\">C3</td><td style=\"padding:6px 10px;border:1px solid #ccc;text-align:center;\">100</td><td style=\"padding:6px 10px;border:1px solid #ccc;text-align:center;\">90</td><td style=\"padding:6px 10px;border:1px solid #ccc;text-align:center;\">105</td></tr><tr style=\"background:#EEF2FA;\"><td style=\"padding:6px 10px;border:1px solid #ccc;\">C4</td><td style=\"padding:6px 10px;border:1px solid #ccc;text-align:center;\">40</td><td style=\"padding:6px 10px;border:1px solid #ccc;text-align:center;\">55</td><td style=\"padding:6px 10px;border:1px solid #ccc;text-align:center;\">60</td></tr></table></div><b>Q:</b> What is the percentage increase in enrollment for C2 from 2022 to 2024?", "options": ["20%", "22%", "25%", "28%", "30%"], "correct": "C", "explanation": "Increase = 75 - 60 = 15. Percentage increase = (15/60) × 100 = 25%."}, {"topic": "Data Interpretation", "question": "<div style=\"background:#F4F6FA;border:1px solid #E1E5EE;border-radius:8px;padding:14px 16px;margin-bottom:14px;font-weight:400;font-size:0.92rem;line-height:1.6;color:#333;\"><b>Data Interpretation — Study the table, then answer Q21&ndash;Q23:</b><br/><br/>Number of students enrolled in 4 courses over 3 years:<br/><table style=\"width:100%;border-collapse:collapse;margin-top:8px;font-size:0.9rem;\"><tr style=\"background:#0D1B4C;color:white;\"><th style=\"padding:6px 10px;border:1px solid #ccc;text-align:left;\">Course</th><th style=\"padding:6px 10px;border:1px solid #ccc;\">2022</th><th style=\"padding:6px 10px;border:1px solid #ccc;\">2023</th><th style=\"padding:6px 10px;border:1px solid #ccc;\">2024</th></tr><tr><td style=\"padding:6px 10px;border:1px solid #ccc;\">C1</td><td style=\"padding:6px 10px;border:1px solid #ccc;text-align:center;\">80</td><td style=\"padding:6px 10px;border:1px solid #ccc;text-align:center;\">95</td><td style=\"padding:6px 10px;border:1px solid #ccc;text-align:center;\">110</td></tr><tr style=\"background:#EEF2FA;\"><td style=\"padding:6px 10px;border:1px solid #ccc;\">C2</td><td style=\"padding:6px 10px;border:1px solid #ccc;text-align:center;\">60</td><td style=\"padding:6px 10px;border:1px solid #ccc;text-align:center;\">65</td><td style=\"padding:6px 10px;border:1px solid #ccc;text-align:center;\">75</td></tr><tr><td style=\"padding:6px 10px;border:1px solid #ccc;\">C3</td><td style=\"padding:6px 10px;border:1px solid #ccc;text-align:center;\">100</td><td style=\"padding:6px 10px;border:1px solid #ccc;text-align:center;\">90</td><td style=\"padding:6px 10px;border:1px solid #ccc;text-align:center;\">105</td></tr><tr style=\"background:#EEF2FA;\"><td style=\"padding:6px 10px;border:1px solid #ccc;\">C4</td><td style=\"padding:6px 10px;border:1px solid #ccc;text-align:center;\">40</td><td style=\"padding:6px 10px;border:1px solid #ccc;text-align:center;\">55</td><td style=\"padding:6px 10px;border:1px solid #ccc;text-align:center;\">60</td></tr></table></div><b>Q:</b> What is the ratio of total enrollment in C1 (across all 3 years) to total enrollment in C4 (across all 3 years)?", "options": ["57:31", "55:30", "60:33", "50:28", "57:30"], "correct": "A", "explanation": "C1 total = 80+95+110 = 285. C4 total = 40+55+60 = 155. Ratio = 285:155, which simplifies (dividing by 5) to 57:31."}, {"topic": "Mensuration", "question": "Find the volume of a cube whose side is 12 cm.", "options": ["1,628 cu cm", "1,728 cu cm", "1,828 cu cm", "1,928 cu cm", "2,028 cu cm"], "correct": "B", "explanation": "Volume of a cube = side³ = 12³ = 12 × 12 × 12 = 1,728 cu cm."}, {"topic": "Probability", "question": "A bag contains 6 red, 5 blue, and 4 green balls. Two balls are drawn at random. Find the probability that both are red.", "options": ["1/7", "2/7", "1/5", "3/14", "1/6"], "correct": "A", "explanation": "Total balls = 15. Total ways to choose 2 = C(15,2) = 105. Ways to choose 2 red from 6 = C(6,2) = 15. Probability = 15/105 = 1/7."}]}, {"id": "reasoning", "title": "Reasoning Ability", "questions": [{"topic": "Syllogism", "question": "Statements: All pens are markers. Some markers are colors.<br/>Conclusions: I. Some pens are colors. II. Some colors are markers.", "options": ["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows", "Cannot be determined"], "correct": "B", "explanation": "All pens are markers + Some markers are colors does NOT guarantee that any pen is among the markers that are colors, so I does not follow. However, II is simply the valid conversion of 'Some markers are colors' to 'Some colors are markers', so II follows."}, {"topic": "Syllogism", "question": "Statements: No mountain is a river. All rivers are water bodies.<br/>Conclusions: I. No mountain is a water body. II. Some water bodies are not mountains.", "options": ["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows", "Cannot be determined"], "correct": "B", "explanation": "No mountain is a river + All rivers are water bodies → Some water bodies (the ones that are rivers) are definitely not mountains, so II follows. I ('No mountain is a water body') is too strong a claim, since other water bodies (not rivers) could still be mountains in principle, so I does not necessarily follow."}, {"topic": "Syllogism", "question": "Statements: Some doctors are engineers. All engineers are graduates.<br/>Conclusions: I. Some doctors are graduates. II. All graduates are engineers.", "options": ["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows", "Cannot be determined"], "correct": "A", "explanation": "Some doctors are engineers + All engineers are graduates → Some doctors are graduates (I follows, a valid 'Some+All=Some' syllogism). II is a converse error ('All engineers are graduates' does not mean 'All graduates are engineers'), so II does not follow."}, {"topic": "Blood Relations", "question": "Pointing to a photograph, Ravi said, 'She is the only daughter of my mother's only brother.' How is the woman related to Ravi?", "options": ["Sister", "Cousin", "Aunt", "Niece", "Mother"], "correct": "B", "explanation": "Ravi's mother's only brother is Ravi's maternal uncle. That uncle's only daughter is Ravi's cousin."}, {"topic": "Blood Relations", "question": "A is the father of B. C is the son of B. D is the sister of C. How is A related to D?", "options": ["Father", "Uncle", "Grandfather", "Brother", "Cousin"], "correct": "C", "explanation": "C and D are siblings, both children of B. Since A is B's father, A is the grandfather of both C and D."}, {"topic": "Blood Relations", "question": "Pointing to a man in a photograph, Meena said, 'His father is the only son of my grandfather.' How is the man related to Meena?", "options": ["Father", "Brother", "Uncle", "Cousin", "Son"], "correct": "B", "explanation": "Meena's grandfather's only son must be Meena's own father (since there is only one son). The man's father is therefore also Meena's father, making the man Meena's brother."}, {"topic": "Direction Sense", "question": "A man walks 10 km towards North, then turns left and walks 5 km, then turns left again and walks 10 km, then turns right and walks 5 km. How far and in which direction is he from the starting point?", "options": ["5 km West", "10 km West", "15 km West", "10 km East", "5 km East"], "correct": "B", "explanation": "North 10 km (facing North) → turn left (now facing West) → 5 km West → turn left again (now facing South) → 10 km South (exactly cancels the initial 10 km North) → turn right (now facing West) → 5 km West. Total westward movement = 5+5 = 10 km West, with zero net North-South displacement."}, {"topic": "Direction Sense", "question": "Point A is 12 m South of Point B. Point C is 5 m East of A. Point D is 5 m East of B. What is the direction of C with respect to D?", "options": ["12 m North", "12 m South", "5 m East", "5 m West", "17 m South"], "correct": "B", "explanation": "Taking B as origin (0,0): A = (0,-12). C = 5m East of A = (5,-12). D = 5m East of B = (5,0). C and D share the same eastward offset (5), so C is directly 12m South of D."}, {"topic": "Coding-Decoding", "question": "In a code, each letter is replaced by the letter 3 positions ahead in the alphabet (wrapping around at the end). What is the code for 'TIGER'?", "options": ["WLJHU", "WLJHV", "VLJHU", "WKJHU", "WLIHU"], "correct": "A", "explanation": "Shifting each letter forward by 3: T+3=W, I+3=L, G+3=J, E+3=H, R+3=U. This gives the code 'WLJHU'."}, {"topic": "Coding-Decoding", "question": "If 'MOUNTAIN' is coded as 'LNTMSZHM' (each letter shifted BACK by 1, wrapping A to Z), what is the code for 'VALLEY' using the same rule?", "options": ["UZKKDX", "UZKKDY", "TZKKDX", "UYKKDX", "UZKLDX"], "correct": "A", "explanation": "Shifting each letter of VALLEY back by 1: V-1=U, A-1=Z (wraps around), L-1=K, L-1=K, E-1=D, Y-1=X. This gives the code 'UZKKDX'."}, {"topic": "Coding-Decoding", "question": "In a certain code, each letter's code is 3 times its position in the alphabet (A=3, B=6, C=9, ...). What is the code for 'FAD'?", "options": ["18-3-12", "15-3-12", "18-3-9", "18-6-12", "21-3-12"], "correct": "A", "explanation": "F is the 6th letter, code = 6×3=18. A is the 1st letter, code = 1×3=3. D is the 4th letter, code = 4×3=12. So 'FAD' is coded as '18-3-12'."}, {"topic": "Inequality", "question": "Statements: A ≥ B &gt; C = D ≥ E<br/>Conclusions: I. A &gt; E   II. B ≥ D", "options": ["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows", "Either I or II follows"], "correct": "C", "explanation": "Chain A≥B>C=D≥E: from A to E, the chain includes a strict '>' (B>C), so A>E holds (I follows). From B to D: B>C=D, so B>D strictly, which also means B≥D is true (II follows)."}, {"topic": "Inequality", "question": "Statements: P &lt; Q ≤ R; R &lt; S<br/>Conclusions: I. P &lt; S   II. Q &lt; S", "options": ["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows", "Either I or II follows"], "correct": "C", "explanation": "Chain: P<Q≤R<S. From P to S: the chain includes strict '<' links, so P<S holds (I follows). From Q to S: Q≤R<S, and since R<S is strict, Q<S also holds (II follows)."}, {"topic": "Inequality", "question": "Statements: M &gt; N; N &gt; O; P &gt; O<br/>Conclusions: I. M &gt; O   II. P &gt; N", "options": ["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows", "Either I or II follows"], "correct": "A", "explanation": "M>N>O gives M>O directly (I follows, a valid chain). However, there is no direct relationship established between P and N — both P and N are only known to be greater than O, so II does not follow."}, {"topic": "Series", "question": "Find the next number in the series: 3, 7, 15, 31, 63, ?", "options": ["119", "123", "125", "127", "129"], "correct": "D", "explanation": "Each term follows the pattern: (previous term × 2) + 1. 3×2+1=7, 7×2+1=15, 15×2+1=31, 31×2+1=63, 63×2+1=127."}, {"topic": "Series", "question": "Find the next number in the series: 100, 96, 89, 79, 66, ?", "options": ["48", "50", "52", "54", "56"], "correct": "B", "explanation": "The differences between consecutive terms are -4, -7, -10, -13, and next -16 (decreasing by 3 each time). Next term = 66 - 16 = 50."}, {"topic": "Series", "question": "Find the WRONG number in the series: 2, 5, 10, 17, 26, 38, 50", "options": ["5", "10", "17", "26", "38"], "correct": "E", "explanation": "This series follows the pattern n²+1: 1²+1=2, 2²+1=5, 3²+1=10, 4²+1=17, 5²+1=26, 6²+1=37 (not 38), 7²+1=50. So 38 is the wrong number; it should be 37."}, {"topic": "Ranking", "question": "In a row of 45 students, Meena is 20th from the left. What is her position from the right?", "options": ["24th", "25th", "26th", "27th", "28th"], "correct": "C", "explanation": "Position from right = Total - Position from left + 1 = 45 - 20 + 1 = 26th."}, {"topic": "Ranking", "question": "Arjun is 12th from the top and 8th from the bottom in a stack of books. How many books are there in total?", "options": ["17", "18", "19", "20", "21"], "correct": "C", "explanation": "Total books = (Position from top) + (Position from bottom) - 1 = 12 + 8 - 1 = 19."}, {"topic": "Ranking", "question": "In a line of people, Karan is 7th from the left and Neha is 9th from the right. If there are exactly 4 people between them (Karan being to the left of Neha), how many people are in the line in total?", "options": ["18", "19", "20", "21", "22"], "correct": "C", "explanation": "Total people = (Karan's position from left) + (Neha's position from right) + (people between them) = 7 + 9 + 4 = 20."}, {"topic": "Puzzle", "question": "<div style=\"background:#F4F6FA;border:1px solid #E1E5EE;border-radius:8px;padding:14px 16px;margin-bottom:14px;font-weight:400;font-size:0.92rem;line-height:1.6;color:#333;\"><b>Linear Seating Puzzle — Study the info, then answer Q21&ndash;Q23:</b><br/><br/>Five friends — J, K, L, M and N — sit in a row, all facing North.<br/>• K sits at the extreme right end.<br/>• N sits immediately to the right of L.<br/>• J sits second to the right of L.<br/>• M sits immediately to the right of J.<br/><br/><i>Solving the puzzle: Since N is immediately right of L, and J is second to the right of L, and M is immediately right of J, the positions L, N, J, M form four CONSECUTIVE seats in that exact order (L, then L+1=N, then L+2=J, then L+3=M). With K fixed at the extreme right end (seat 5), the only way to fit four consecutive seats before it is L=1, N=2, J=3, M=4, K=5. Final seating order (left to right): <b>L, N, J, M, K</b>.</i></div><b>Q:</b> Who sits third from the left?", "options": ["L", "N", "J", "M", "K"], "correct": "C", "explanation": "From the solved order L-N-J-M-K (left to right), the person at the 3rd position from the left is J."}, {"topic": "Puzzle", "question": "<div style=\"background:#F4F6FA;border:1px solid #E1E5EE;border-radius:8px;padding:14px 16px;margin-bottom:14px;font-weight:400;font-size:0.92rem;line-height:1.6;color:#333;\"><b>Linear Seating Puzzle — Study the info, then answer Q21&ndash;Q23:</b><br/><br/>Five friends — J, K, L, M and N — sit in a row, all facing North.<br/>• K sits at the extreme right end.<br/>• N sits immediately to the right of L.<br/>• J sits second to the right of L.<br/>• M sits immediately to the right of J.<br/><br/><i>Solving the puzzle: Since N is immediately right of L, and J is second to the right of L, and M is immediately right of J, the positions L, N, J, M form four CONSECUTIVE seats in that exact order (L, then L+1=N, then L+2=J, then L+3=M). With K fixed at the extreme right end (seat 5), the only way to fit four consecutive seats before it is L=1, N=2, J=3, M=4, K=5. Final seating order (left to right): <b>L, N, J, M, K</b>.</i></div><b>Q:</b> How many people sit between N and K?", "options": ["None", "One", "Two", "Three", "Four"], "correct": "C", "explanation": "N is at position 2 and K is at position 5. The people between them are at positions 3 and 4 (J and M) — a total of two people."}, {"topic": "Puzzle", "question": "<div style=\"background:#F4F6FA;border:1px solid #E1E5EE;border-radius:8px;padding:14px 16px;margin-bottom:14px;font-weight:400;font-size:0.92rem;line-height:1.6;color:#333;\"><b>Linear Seating Puzzle — Study the info, then answer Q21&ndash;Q23:</b><br/><br/>Five friends — J, K, L, M and N — sit in a row, all facing North.<br/>• K sits at the extreme right end.<br/>• N sits immediately to the right of L.<br/>• J sits second to the right of L.<br/>• M sits immediately to the right of J.<br/><br/><i>Solving the puzzle: Since N is immediately right of L, and J is second to the right of L, and M is immediately right of J, the positions L, N, J, M form four CONSECUTIVE seats in that exact order (L, then L+1=N, then L+2=J, then L+3=M). With K fixed at the extreme right end (seat 5), the only way to fit four consecutive seats before it is L=1, N=2, J=3, M=4, K=5. Final seating order (left to right): <b>L, N, J, M, K</b>.</i></div><b>Q:</b> Who sits immediately to the left of M?", "options": ["L", "N", "J", "K", "None of these"], "correct": "C", "explanation": "M is at position 4. The person immediately to its left (position 3) is J."}, {"topic": "Logical Reasoning", "question": "Statement: 'All applicants for the scholarship must submit their academic transcripts by the March 15 deadline to be considered for the award.' Which of the following can be logically concluded?", "options": ["All applicants who submit transcripts by March 15 will receive the scholarship", "An applicant who fails to submit transcripts by March 15 will not be considered for the award", "The scholarship amount depends on transcript quality", "Only applicants with perfect grades may apply", "The deadline can be extended upon request"], "correct": "B", "explanation": "Submitting transcripts by the deadline is stated as a NECESSARY condition for being considered — so missing the deadline means the applicant will not be considered. Option A wrongly treats this necessary condition as also being sufficient for actually winning the scholarship."}, {"topic": "Logical Reasoning", "question": "Statement: 'Since the company began offering unlimited paid time off, employee-reported burnout scores have decreased by 20%.' Which of the following, if true, would most STRENGTHEN the claim that the new policy caused the decrease in burnout?", "options": ["The company also reduced average weekly working hours during the same period", "Employees who used the most PTO under the new policy showed the largest decreases in burnout scores, while those using little PTO showed almost no change", "The survey used to measure burnout was redesigned during this period", "A competing company reported similar burnout reductions without changing its PTO policy", "The company hired additional staff during this period"], "correct": "B", "explanation": "A clear dose-response relationship — more PTO usage correlating with a larger burnout decrease, and little usage correlating with little change — directly strengthens the causal link between the policy and the outcome. The other options either introduce confounding factors or actively weaken the claim."}]}, {"id": "pk", "title": "Professional Knowledge", "questions": [{"topic": "DBMS", "question": "Which normal form specifically deals with eliminating multi-valued dependencies from a relation?", "options": ["2NF", "3NF", "BCNF", "4NF", "5NF"], "correct": "D", "explanation": "4NF (Fourth Normal Form) eliminates multi-valued dependencies, requiring that a table not contain two or more independent multi-valued facts about an entity."}, {"topic": "DBMS", "question": "Which SQL clause combines the result sets of two or more SELECT statements and automatically removes duplicate rows?", "options": ["JOIN", "UNION", "UNION ALL", "INTERSECT", "MERGE"], "correct": "B", "explanation": "UNION combines result sets from multiple SELECT queries and automatically removes duplicate rows, unlike UNION ALL, which keeps all duplicates."}, {"topic": "DBMS", "question": "Defining a PRIMARY KEY constraint on a column automatically creates which of the following on that column?", "options": ["A CHECK constraint only", "A unique index enforcing entity integrity", "A DEFAULT value", "A foreign key reference", "A comment/annotation only"], "correct": "B", "explanation": "A PRIMARY KEY constraint automatically creates a unique index on the specified column(s), enforcing that every value is unique and non-null, thereby maintaining entity integrity."}, {"topic": "DBMS", "question": "What is the key difference between COUNT(*) and COUNT(column_name) in SQL?", "options": ["They are always identical in every case", "COUNT(*) counts all rows including NULLs in any column, while COUNT(column_name) excludes rows where that column is NULL", "COUNT(column_name) is always faster regardless of indexing", "COUNT(*) ignores duplicate rows automatically", "COUNT(column_name) counts only NULL values in that column"], "correct": "B", "explanation": "COUNT(*) counts every row in the result set regardless of NULL values, whereas COUNT(column_name) only counts rows where that specific column holds a non-NULL value."}, {"topic": "DBMS", "question": "Which database design technique intentionally introduces redundancy to improve read/query performance, commonly used in reporting and data warehouse systems?", "options": ["Normalization", "Denormalization", "Indexing", "Partitioning", "Sharding"], "correct": "B", "explanation": "Denormalization deliberately adds redundant data to reduce the need for complex joins, improving read performance at some cost to write complexity and storage space."}, {"topic": "DBMS", "question": "Under a RESTRICT (or NO ACTION) referential integrity constraint, which operation is blocked by default if a parent row is still referenced by existing child rows?", "options": ["SELECT on the parent row", "INSERT of a new child row", "DELETE of the referenced parent row", "UPDATE of unrelated parent columns", "CREATE INDEX on the parent table"], "correct": "C", "explanation": "A RESTRICT/NO ACTION referential integrity constraint prevents deleting (or changing the key of) a parent row while child rows still reference it via a foreign key."}, {"topic": "OS", "question": "Which CPU scheduling algorithm can cause starvation of low-priority processes if 'aging' is not implemented?", "options": ["FCFS", "Round Robin", "Priority Scheduling", "SJF (non-preemptive, no ties)", "Multilevel Queue without feedback"], "correct": "C", "explanation": "In Priority Scheduling, low-priority processes can be perpetually delayed (starved) if higher-priority processes keep arriving, unless aging is used to gradually increase a waiting process's priority."}, {"topic": "OS", "question": "What is the term for temporarily moving an entire inactive process from RAM to disk to free up memory for other processes?", "options": ["Paging", "Swapping", "Segmentation", "Caching", "Spooling"], "correct": "B", "explanation": "Swapping moves an entire process out of main memory to disk (and back in later), freeing RAM for other processes, distinct from paging which moves individual fixed-size pages."}, {"topic": "OS", "question": "Which condition must exist for a race condition to occur between two processes or threads?", "options": ["They must access shared data concurrently without proper synchronization", "They must run on physically different machines", "They must have identical scheduling priorities", "They must be compiled from the same source file", "They must both perform only I/O operations"], "correct": "A", "explanation": "A race condition occurs when multiple processes/threads access and manipulate shared data concurrently, and the final outcome depends on the unpredictable timing of their execution, due to a lack of proper synchronization."}, {"topic": "OS", "question": "In Round Robin scheduling, if the time quantum is set LARGER than the longest process's total burst time, how does the scheduler behave?", "options": ["It behaves identically to FCFS", "It causes deadlock", "It causes starvation of long processes", "It behaves like SJF", "It causes thrashing"], "correct": "A", "explanation": "If the time quantum exceeds every process's burst time, no process needs more than one quantum to finish, so processes complete in arrival order — identical behavior to FCFS."}, {"topic": "OS", "question": "Which memory allocation strategy searches for the SMALLEST free block that is still large enough to satisfy a request, aiming to minimize leftover fragment size?", "options": ["First Fit", "Best Fit", "Worst Fit", "Next Fit", "Buddy System"], "correct": "B", "explanation": "Best Fit scans all free blocks and selects the smallest one that can still accommodate the request, aiming to leave the smallest possible leftover fragment."}, {"topic": "OS", "question": "What is the primary purpose of a Translation Lookaside Buffer (TLB) in a system using paging?", "options": ["To store recently used page table entries for faster virtual-to-physical address translation", "To manage disk I/O scheduling order", "To handle interrupt priority levels", "To compress memory pages to save space", "To schedule which CPU core runs next"], "correct": "A", "explanation": "A TLB is a small, fast cache that stores recently used page table entries, avoiding a full page table lookup in memory for every address translation and significantly speeding up memory access."}, {"topic": "Networks", "question": "Which protocol is used to securely transfer files over an encrypted SSH connection?", "options": ["FTP", "SFTP", "HTTP", "SMTP", "Telnet"], "correct": "B", "explanation": "SFTP (SSH File Transfer Protocol) transfers files over a secure, encrypted SSH connection, unlike plain FTP which sends data (including credentials) unencrypted."}, {"topic": "Networks", "question": "Which IPv4 address class is reserved exclusively for multicast addressing?", "options": ["Class A", "Class B", "Class C", "Class D", "Class E"], "correct": "D", "explanation": "Class D addresses (224.0.0.0 to 239.255.255.255) are reserved exclusively for multicast group addressing, not for individual host assignment."}, {"topic": "Networks", "question": "What is the main advantage of full-duplex Ethernet over half-duplex in terms of collisions?", "options": ["Full-duplex eliminates collisions entirely by allowing simultaneous send/receive on separate channels", "Full-duplex only doubles the maximum cable length", "Full-duplex requires a shared hub to function", "Full-duplex behaves identically to half-duplex", "Full-duplex works only over fiber optic cabling"], "correct": "A", "explanation": "Full-duplex Ethernet uses separate transmit and receive paths, allowing simultaneous two-way communication and completely eliminating the possibility of collisions that occur in half-duplex shared-medium communication."}, {"topic": "Networks", "question": "Which network topology connects every device to a central hub or switch, making it easy to add/remove devices but creating a single point of failure at the center?", "options": ["Bus", "Ring", "Star", "Mesh", "Tree"], "correct": "C", "explanation": "In a Star topology, all devices connect individually to a central hub/switch; this makes adding/removing devices easy, but if the central device fails, the whole network segment goes down."}, {"topic": "Networks", "question": "Which transport layer protocol is preferred for applications like video conferencing, where speed matters more than guaranteed, ordered delivery?", "options": ["TCP", "UDP", "IP", "ICMP", "ARP"], "correct": "B", "explanation": "UDP (User Datagram Protocol) is connectionless with minimal overhead, making it faster and better suited for real-time applications like video/voice calls, where occasional packet loss is preferable to the delays caused by TCP's reliability mechanisms."}, {"topic": "DSA", "question": "Which combination of data structures is most suitable for implementing an LRU (Least Recently Used) cache with O(1) average time complexity for both get and put operations?", "options": ["A plain array only", "A singly linked list only", "A combination of a Hash Map and a Doubly Linked List", "A Binary Search Tree", "A simple Stack"], "correct": "C", "explanation": "A Hash Map provides O(1) lookup of nodes, while a Doubly Linked List allows O(1) removal/reinsertion at both ends to track usage order — together they give O(1) average time for LRU cache operations."}, {"topic": "DSA", "question": "What is the worst-case time complexity of inserting a new element into a balanced AVL tree containing n nodes?", "options": ["O(1)", "O(log n)", "O(n)", "O(n log n)", "O(n^2)"], "correct": "B", "explanation": "Since an AVL tree is kept balanced (height O(log n)) via rotations after every insertion, both the search-to-insert-position and the rebalancing take O(log n) time in the worst case."}, {"topic": "DSA", "question": "In a singly linked list, if you are given a pointer to a node (not the tail) and want to effectively 'delete' it in O(1) time without traversing from the head, which technique is used?", "options": ["Traverse from the head to find the predecessor node first", "Copy the next node's data into the current node, then delete the next node instead", "Convert the list to a doubly linked list first", "It cannot be done in O(1) time under any circumstances", "Reverse the entire list first, then delete"], "correct": "B", "explanation": "A well-known trick: copy the data from the next node into the current node, then delete/bypass the next node — effectively 'deleting' the current node's value in O(1) time without needing the predecessor."}, {"topic": "DSA", "question": "What is the time complexity of Kruskal's algorithm for finding a Minimum Spanning Tree with E edges, dominated by sorting the edges (using an efficient Union-Find structure)?", "options": ["O(V)", "O(E log E)", "O(V^2)", "O(E^2)", "O(log V)"], "correct": "B", "explanation": "Kruskal's algorithm sorts all E edges by weight (O(E log E)) and then processes them using a near-constant-time Union-Find structure, making the sorting step the dominant cost overall."}, {"topic": "DSA", "question": "Which traversal of a binary tree would you use to create a clone (deep copy) of it, ensuring each parent node is created before its children?", "options": ["Inorder", "Postorder", "Preorder", "Level order only", "None of these"], "correct": "C", "explanation": "Preorder traversal (Root-Left-Right) visits the root/parent before its children, which is exactly the order needed to construct a copy of the tree top-down."}, {"topic": "DSA", "question": "What is the primary advantage of a B+ Tree over a standard B Tree for database indexing?", "options": ["B+ Trees store data only in internal nodes", "B+ Trees store all actual data in leaf nodes, which are linked together for efficient range queries and sequential access", "B+ Trees cannot be balanced", "B+ Trees are always shallower than a B Tree holding the same data", "B+ Trees do not support search operations at all"], "correct": "B", "explanation": "In a B+ Tree, all actual data resides in the leaf nodes, and these leaves are linked in a chain, enabling fast sequential scans and efficient range queries — a key advantage over a standard B Tree."}, {"topic": "OOPS", "question": "Which OOPS concept allows a single interface (like a method name) to be used for a general class of actions, with the specific behavior determined by the actual object type (e.g., 'draw()' behaving differently for a Circle vs a Square)?", "options": ["Encapsulation", "Polymorphism", "Inheritance", "Abstraction", "Composition"], "correct": "B", "explanation": "Polymorphism ('many forms') allows the same method name/interface to produce different behavior depending on the actual object it's called on, as in method overriding."}, {"topic": "OOPS", "question": "In Java, which keyword is used inside a subclass to explicitly call the constructor of its parent (super) class?", "options": ["this", "super", "extends", "implements", "base"], "correct": "B", "explanation": "The 'super' keyword, when used as super(...), explicitly invokes the parent class's constructor from within a subclass's constructor."}, {"topic": "OOPS", "question": "Method overloading (same method name, different parameter lists, within the same class) is primarily an example of which concept?", "options": ["Runtime Polymorphism", "Compile-Time Polymorphism", "Inheritance", "Encapsulation", "Abstraction"], "correct": "B", "explanation": "Method Overloading is resolved at compile time based on the number/type of arguments, making it a form of Compile-Time (Static) Polymorphism, unlike method overriding which is resolved at runtime."}, {"topic": "OOPS", "question": "Which Java access modifier allows a member to be accessed by any class within the same package, but NOT by subclasses located in different packages?", "options": ["private", "protected", "public", "default (package-private)", "final"], "correct": "D", "explanation": "The default (package-private) access level — when no modifier is specified — restricts access to classes within the same package only, unlike 'protected', which also allows access from subclasses in other packages."}, {"topic": "OOPS", "question": "What is the primary restriction on instantiating an abstract class directly?", "options": ["Abstract classes can always be instantiated like any concrete class", "An abstract class cannot be instantiated directly, since it may contain unimplemented (abstract) methods", "Abstract classes can never have any constructors", "Abstract classes cannot contain any concrete (implemented) methods", "There is no restriction at all"], "correct": "B", "explanation": "An abstract class cannot be instantiated directly precisely because it may declare abstract methods with no implementation; a concrete subclass must implement them before objects can be created."}, {"topic": "Software Engineering", "question": "Which requirements elicitation technique involves directly observing users performing their tasks within their actual work environment?", "options": ["Brainstorming", "Contextual Inquiry (Observation)", "Prototyping", "Use Case Modeling", "Interviewing only"], "correct": "B", "explanation": "Contextual Inquiry involves observing and often interacting with users as they perform real tasks in their natural work setting, revealing needs that interviews alone might miss."}, {"topic": "Software Engineering", "question": "In Agile methodology, what is the primary purpose of the 'Daily Stand-up' (Daily Scrum) meeting?", "options": ["To conduct detailed code reviews", "For team members to briefly synchronize on progress, plans, and blockers", "To finalize the project budget", "To interview new candidates", "To conduct annual performance reviews"], "correct": "B", "explanation": "The Daily Stand-up is a short, time-boxed meeting where team members quickly share what they did, what they plan to do next, and any blockers — keeping the team synchronized."}, {"topic": "Software Engineering", "question": "Which software quality attribute refers to the ease with which a system can be modified to fix defects, improve performance, or adapt to a changed environment?", "options": ["Usability", "Maintainability", "Portability", "Reliability", "Efficiency"], "correct": "B", "explanation": "Maintainability specifically measures how easily a software system can be modified — for corrective fixes, adaptive changes, or perfective improvements."}, {"topic": "Software Engineering", "question": "What does 'technical debt' refer to in software engineering?", "options": ["The literal monetary cost of purchasing software licenses", "The implied future cost of rework caused by choosing an easy/quick solution now instead of a better approach that would take longer", "The cost of hiring additional technical staff", "A type of database transaction rollback cost", "The depreciation of computer hardware over time"], "correct": "B", "explanation": "Technical debt is a metaphor for the extra future rework created when developers choose an expedient but suboptimal solution now, rather than investing more time in a better long-term approach."}, {"topic": "Software Engineering", "question": "Which type of software maintenance is performed to prevent potential future problems (e.g., restructuring code for better long-term maintainability), even though no current defect exists?", "options": ["Corrective Maintenance", "Adaptive Maintenance", "Perfective Maintenance", "Preventive Maintenance", "Emergency Maintenance"], "correct": "D", "explanation": "Preventive Maintenance proactively addresses potential future issues (e.g., refactoring fragile code) before they cause actual defects, distinct from Corrective (fixing bugs) or Adaptive (responding to environment changes) maintenance."}, {"topic": "COA", "question": "Which type of memory is directly addressable by the CPU and is the fastest form of storage, located within the CPU itself?", "options": ["Cache Memory", "RAM", "Registers", "ROM", "SSD"], "correct": "C", "explanation": "CPU Registers are the fastest storage elements, located directly inside the processor, faster even than cache memory, though with very limited capacity."}, {"topic": "COA", "question": "In pipelining, what is the term for a hazard that occurs when two instructions attempt to use the same hardware resource (e.g., the same memory unit) at the same time?", "options": ["Data Hazard", "Control Hazard", "Structural Hazard", "Branch Hazard", "Memory Leak"], "correct": "C", "explanation": "A Structural Hazard arises when two or more instructions in the pipeline need the same hardware resource simultaneously, and the hardware cannot support both accesses at once."}, {"topic": "COA", "question": "What does the acronym 'ISA' stand for in computer architecture?", "options": ["Internal System Architecture", "Instruction Set Architecture", "Integrated Storage Array", "Interconnected System Access", "Instruction Sequencing Algorithm"], "correct": "B", "explanation": "ISA (Instruction Set Architecture) defines the set of instructions, addressing modes, registers, and data types that a processor can understand and execute."}, {"topic": "COA", "question": "Which system bus is responsible for carrying only control signals, such as Read/Write and Interrupt requests, rather than data or addresses?", "options": ["Data Bus", "Address Bus", "Control Bus", "System Bus (as a distinct generic type)", "Local Bus"], "correct": "C", "explanation": "The Control Bus carries command and coordination signals (Read, Write, Interrupt, Clock, Reset, etc.) between the CPU, memory, and I/O devices."}, {"topic": "COA", "question": "If a computer has a 32-bit address bus, what is the maximum amount of memory it can directly address?", "options": ["2 GB", "4 GB", "8 GB", "16 GB", "32 GB"], "correct": "B", "explanation": "A 32-bit address bus can represent 2^32 distinct addresses, which equals 4,294,967,296 bytes, i.e., exactly 4 GB of directly addressable memory."}, {"topic": "Cyber Security", "question": "Which type of malware encrypts a victim's files and demands payment for the decryption key?", "options": ["Worm", "Trojan", "Ransomware", "Spyware", "Adware"], "correct": "C", "explanation": "Ransomware encrypts a victim's files (or locks the system) and demands a ransom payment, typically in cryptocurrency, in exchange for the decryption key."}, {"topic": "Cyber Security", "question": "What is the primary purpose of a Digital Certificate in secure web communication (HTTPS)?", "options": ["To encrypt the entire hard drive of the server", "To bind a public key to a verified identity, issued by a trusted Certificate Authority", "To store user passwords securely", "To automatically block all malicious websites", "To compress web traffic for faster loading"], "correct": "B", "explanation": "A Digital Certificate, issued by a trusted Certificate Authority (CA), binds a public key to a verified identity (like a website's domain), allowing browsers to confirm they're communicating with the legitimate server."}, {"topic": "Cyber Security", "question": "Which type of attack involves an attacker secretly intercepting communication between two parties, potentially reading or altering the messages without their knowledge?", "options": ["Denial of Service", "Man-in-the-Middle Attack", "SQL Injection", "Phishing", "Brute Force Attack"], "correct": "B", "explanation": "A Man-in-the-Middle (MITM) attack involves an attacker secretly positioning themselves between two communicating parties, intercepting and potentially altering the data exchanged."}, {"topic": "Cyber Security", "question": "What does the principle of 'least privilege' recommend in cybersecurity?", "options": ["Granting all users administrator access for convenience", "Granting users and systems only the minimum access rights necessary to perform their required tasks", "Removing all access controls entirely from the system", "Granting maximum privileges to all new employees by default", "Sharing administrator passwords across the whole team"], "correct": "B", "explanation": "The Principle of Least Privilege states that users and systems should be granted only the minimum level of access needed to perform their required functions, limiting potential damage from errors or compromise."}, {"topic": "Cyber Security", "question": "Which security testing technique simulates a real-world attack on a system, with authorization, to identify exploitable vulnerabilities?", "options": ["Code Review", "Penetration Testing", "Unit Testing", "Static Analysis only", "Load Testing"], "correct": "B", "explanation": "Penetration Testing (pen testing) involves authorized security professionals simulating real attacks against a system to discover and demonstrate exploitable vulnerabilities before malicious actors can."}, {"topic": "Data Warehouse", "question": "In a Star Schema, what is the typical relationship between the fact table and the dimension tables?", "options": ["Many fact tables connect to one dimension table", "One central fact table connects directly to multiple denormalized dimension tables", "Dimension tables connect only to each other", "No direct relationship exists between them", "Fact tables cannot connect to dimension tables directly"], "correct": "B", "explanation": "A Star Schema has one central fact table directly linked to several denormalized (flat) dimension tables, forming a star-like layout when diagrammed."}, {"topic": "Data Warehouse", "question": "What does 'ELT' stand for, as an alternative approach to traditional 'ETL' in modern data pipelines?", "options": ["Extract, Load, Transform", "Export, Load, Transfer", "Extract, Link, Transform", "Evaluate, Load, Test", "Extract, Load, Test"], "correct": "A", "explanation": "ELT (Extract, Load, Transform) loads raw data into the target system first and performs transformations afterward (often using the target system's own processing power), reversing the order of traditional ETL."}, {"topic": "Data Warehouse", "question": "Which OLAP operation rotates the axes of a data cube to provide an alternative view/presentation of the same data?", "options": ["Roll-up", "Drill-down", "Slice", "Dice", "Pivot"], "correct": "E", "explanation": "The Pivot (Rotate) operation reorients the data cube's axes — for example, swapping rows and columns — to present the same underlying data from a different perspective."}, {"topic": "Data Warehouse", "question": "What is a 'Data Mart' primarily designed to serve?", "options": ["The entire organization's complete data needs", "A specific department or business function's focused data needs", "Only real-time transactional processing", "External customers directly", "Only unstructured data storage"], "correct": "B", "explanation": "A Data Mart is a smaller, focused subset of a data warehouse tailored to the specific analytical needs of a single department or business function (e.g., Sales or HR)."}, {"topic": "Data Warehouse", "question": "In dimensional modeling, what term describes a fact table row with no associated numeric measures, used only to record that an event occurred?", "options": ["Transaction Fact", "Factless Fact Table row", "Accumulating Snapshot", "Periodic Snapshot", "Aggregate Fact"], "correct": "B", "explanation": "A Factless Fact Table row records the occurrence of an event (e.g., a student attending a class) purely through its combination of dimension keys, without any associated numeric measure."}, {"topic": "Programming", "question": "What does the following Python code print?<br/>def f(x, y=[]):<br/>&nbsp;&nbsp;&nbsp;&nbsp;y.append(x)<br/>&nbsp;&nbsp;&nbsp;&nbsp;return y<br/>print(f(1))<br/>print(f(2))", "options": ["[1] then [2]", "[1] then [1, 2]", "[1, 2] then [1, 2]", "Raises an error", "[2] then [1, 2]"], "correct": "B", "explanation": "A classic Python gotcha: the default mutable argument y=[] is created only ONCE, when the function is defined, and is shared across all calls that don't pass their own y. So f(1) appends 1 to the shared list (giving [1]), and f(2) appends 2 to that SAME list (giving [1, 2])."}, {"topic": "Programming", "question": "In Java, what is the output of the following code?<br/>String a = \"hello\";<br/>String b = \"hello\";<br/>System.out.println(a == b);", "options": ["true", "false", "Compilation error", "Runtime exception", "Depends unpredictably on JVM version"], "correct": "A", "explanation": "Java interns string literals in a special 'string pool' — since both a and b are literal 'hello' strings, they refer to the SAME object in the pool, so the reference comparison (==) returns true."}]}];
